window.bookSummaryJSON = "<p><b><i>Three lives come together in this truly epic fantasy where magic users go missing, old gods return, and creatures of light ravage the land.</i></b><br> <br> A high general with a dark voice in his head that begs to be released.<br> <br> A sheltered young woman addicted to magic.<br> <br> A reckless young man whose life changes after he dies.<br> <br> Together, they will change the world—whether they intend to or not.<br> <br> <b>INCLUDES:</b> 1) Voice of War, 2) Stones of Light, 3) Bonds of Chaos</p>"; 
